static inline bool money_eq(money a, money b) { return a.cents == b.cents; }
static inline bool money_less(money a, money b) { return a.cents < b.cents; }

/* C11: select the function NAME, keep the call outside the _Generic */
#define eq(a, b) _Generic((a), money: money_eq, vec3: vec3_eq)((a), (b))
#define less(a, b) _Generic((a), money: money_less, vec3: vec3_less)((a), (b))
